// Turns match events and on-court "moments" into party prompts.

import { MatchEvent, MatchState, Team, other } from './scoring';
import type { GameRecord } from '../storage';
import { FINISH_SIPS, Spice, renderPenalty } from './spice';

/** Sound effects in assets/sounds (generated by scripts/make_sounds.py). */
export type SoundId =
  | 'airhorn'
  | 'kazoo'
  | 'sadtrombone'
  | 'boing'
  | 'slideup'
  | 'slidedown'
  | 'honk'
  | 'bonk'
  | 'whoosh'
  | 'drumroll';

export interface PartyPrompt {
  emoji: string;
  title: string;
  body: string;
  /** Big moments get a full-screen takeover instead of a toast. */
  big?: boolean;
  sound?: SoundId;
  /** Party Rules: the sips this prompt puts on the Bar Tab, and whose tab. */
  tab?: TabCharge;
}

/** Sips added to one team's Bar Tab, or to both. */
export interface TabCharge {
  team: Team | 'both';
  sips: number;
}

export type MomentId = 'net' | 'ace' | 'kitchen' | 'erne' | 'longRally' | 'bodyShot' | 'wayOut';

export interface Moment {
  id: MomentId;
  emoji: string;
  label: string;
  /** Asked before the prompt: which team did it? */
  ask: string;
  /** Every moment ends the rally: does the team that did it win it, or lose it? */
  rallyGoesTo: 'doer' | 'other';
}

export const MOMENTS: Moment[] = [
  { id: 'net', emoji: '🥅', label: 'Into the net', ask: 'Who hit the net?', rallyGoesTo: 'other' },
  { id: 'ace', emoji: '⚡', label: 'Ace', ask: 'Who served the ace?', rallyGoesTo: 'doer' },
  { id: 'kitchen', emoji: '🍳', label: 'Kitchen fault', ask: 'Who faulted?', rallyGoesTo: 'other' },
  // Any jaw-dropper: an Erne, an ATP, an unreturnable drop.
  { id: 'erne', emoji: '🦅', label: 'Highlight shot', ask: 'Who hit the highlight?', rallyGoesTo: 'doer' },
  { id: 'longRally', emoji: '🔁', label: '10+ rally', ask: 'Who won the rally?', rallyGoesTo: 'doer' },
  { id: 'bodyShot', emoji: '🎯', label: 'Body shot', ask: 'Who hit the body shot?', rallyGoesTo: 'doer' },
  { id: 'wayOut', emoji: '🚀', label: 'Way out', ask: 'Who hit it out?', rallyGoesTo: 'other' },
];

/** The team that wins the rally when `doer` caused this moment. */
export function momentRallyWinner(id: MomentId, doer: Team): Team {
  return MOMENTS.find((m) => m.id === id)!.rallyGoesTo === 'doer' ? doer : other(doer);
}

// {who} is the team that did it, {them} the other team. `pays`: whose Bar Tab the sips go on.
const MOMENT_TEXT: Record<MomentId, { title: string; body: string; sound: SoundId; pays: 'who' | 'them' | 'both' }> = {
  net: { title: 'Net Tax', body: '{who} fed the net. Pay the tax: {sips:1}.', sound: 'sadtrombone', pays: 'who' },
  ace: { title: 'Ace!', body: 'Untouchable serve from {who}. {them}, {sips:1}.', sound: 'boing', pays: 'them' },
  kitchen: { title: 'Kitchen Fault', body: 'Toes over the line! {who}, {sips:1}.', sound: 'honk', pays: 'who' },
  erne: { title: 'Highlight Reel', body: 'Legendary shot by {who}! {them}, {sips:3}.', sound: 'airhorn', pays: 'them' },
  longRally: {
    title: 'Dink War',
    body: '{who} won a movie of a rally. {them}, {sips:1}. Everyone else too.',
    sound: 'kazoo',
    pays: 'both',
  },
  bodyShot: { title: 'Body Shot', body: '{them} got tagged. Payback: {who}, {sips:1}.', sound: 'bonk', pays: 'who' },
  wayOut: { title: 'Launched It', body: 'That ball is in orbit. {who}, {sips:2}.', sound: 'slideup', pays: 'who' },
};

/** How many sips a prompt's text asks for (its first {sips:N}). */
const sipsIn = (text: string) => Number(text.match(/\{sips:(\d+)\}/)?.[1] ?? 0);

const fill = (text: string, vars: Record<string, string>, spice: Spice, rng: () => number, tab = false) =>
  renderPenalty(
    text.replace(/\{(\w+)\}/g, (m, key: string) => vars[key] ?? m),
    spice,
    rng,
    { tab },
  );

export function momentPrompt(
  id: MomentId,
  who: string,
  spice: Spice,
  them = 'the other team',
  rng: () => number = Math.random,
  /** Party Rules: put the sips on the Bar Tab of `whoTeam` (the team that did it) or the other team. */
  opts: { tab?: boolean; whoTeam?: Team } = {},
): PartyPrompt {
  const moment = MOMENTS.find((m) => m.id === id)!;
  const t = MOMENT_TEXT[id];
  const prompt: PartyPrompt = {
    emoji: moment.emoji,
    title: t.title,
    body: fill(t.body, { who, them }, spice, rng, opts.tab),
    sound: t.sound,
  };
  if (opts.tab && opts.whoTeam !== undefined) {
    const team = t.pays === 'both' ? 'both' : t.pays === 'who' ? opts.whoTeam : other(opts.whoTeam);
    prompt.tab = { team, sips: sipsIn(t.body) };
  }
  return prompt;
}

/** "Sam & Alex win!" but "Lob Squad wins!" */
export const winsTitle = (team: string) => `${team} ${/ & /.test(team) ? 'win' : 'wins'}!`;

/** Chance that a side-out calls for a sip. Kept low: side-outs happen every few rallies. */
export const SIDE_OUT_CHANCE = 0.1;

/** Ties only call for a sip late in the game (7-7 and up in a game to 11). */
export const lateTie = (target: number) => Math.ceil(target * 0.6);

/**
 * Pick at most one prompt for a rally's events. Rarer, bigger events win.
 * Side-outs only trigger sometimes and ties only late, so the drinking stays light.
 */
export function promptForEvents(
  events: MatchEvent[],
  state: MatchState,
  spice: Spice,
  rng: () => number = Math.random,
  /** `tab`: Party Rules, so sips go on the Bar Tab (each prompt says whose). */
  opts: { calm?: boolean; tab?: boolean } = {},
): PartyPrompt | null {
  const name = (t: Team) => state.config.teamNames[t];
  const f = (text: string, vars: Record<string, string> = {}) => fill(text, vars, spice, rng, opts.tab);
  const charge = (team: Team | 'both', sips: number) => (opts.tab ? { tab: { team, sips } } : {});

  const over = events.find((e) => e.type === 'gameOver');
  if (over && over.type === 'gameOver') {
    const loser = name(other(over.winner));
    if (over.pickled) {
      return {
        emoji: '🥒',
        title: 'PICKLED!',
        body: f('{loser} got skunked! Pickle Penalty: {finish}, then a lap of shame.', { loser }),
        big: true,
        sound: 'airhorn',
        ...charge(other(over.winner), FINISH_SIPS),
      };
    }
    return {
      emoji: '🏆',
      title: winsTitle(name(over.winner)),
      body: f('{loser}, {sips:2}. The winners pick the next house rule.', { loser }),
      big: true,
      sound: 'kazoo',
      ...charge(other(over.winner), 2),
    };
  }

  const watch = events.find((e) => e.type === 'pickleWatch');
  if (watch && watch.type === 'pickleWatch') {
    return {
      emoji: '👀',
      title: 'Pickle Watch',
      body: f('{team} has zero points. Score one now or get pickled.', { team: name(watch.team) }),
      sound: 'drumroll',
    };
  }

  // Calm mode: only the moments that matter (Pickle Watch, game point, the end of the game).
  if (opts.calm) {
    const gp = events.find((e) => e.type === 'gamePoint');
    if (!gp || gp.type !== 'gamePoint') return null;
  }

  const streak = events.find((e) => e.type === 'streak');
  if (streak && streak.type === 'streak') {
    const sips = streak.length >= 6 ? 2 : 1;
    return {
      emoji: '🔥',
      title: `${streak.length}-point heater`,
      body: f(`{team} is cooking. {victims} must {sips:${sips}}.`, {
        team: name(streak.team),
        victims: name(other(streak.team)),
      }),
      sound: 'slideup',
      ...charge(other(streak.team), sips),
    };
  }

  const gamePoint = events.find((e) => e.type === 'gamePoint');
  if (gamePoint && gamePoint.type === 'gamePoint') {
    return {
      emoji: '⏳',
      title: 'Game Point',
      body: f('{team} is one away. {other} — {sips:1} for courage.', {
        team: name(gamePoint.team),
        other: name(other(gamePoint.team)),
      }),
      sound: 'drumroll',
      ...charge(other(gamePoint.team), 1),
    };
  }

  const tied = events.find((e) => e.type === 'tied');
  if (tied && tied.type === 'tied' && tied.score >= lateTie(state.config.target)) {
    return {
      emoji: '🤝',
      title: `Tied at ${tied.score}`,
      body: f('Dead even. {a} and {b}, everybody {sips:1}.', { a: name(0), b: name(1) }),
      sound: 'boing',
      ...charge('both', 1),
    };
  }

  const sideOut = events.find((e) => e.type === 'sideOut');
  if (sideOut && sideOut.type === 'sideOut' && rng() < SIDE_OUT_CHANCE) {
    return {
      emoji: '🔄',
      title: 'Serve Tax',
      body: f('{team} lost the serve. Server, {sips:1}.', { team: name(other(sideOut.to)) }),
      sound: 'slidedown',
      ...charge(other(sideOut.to), 1),
    };
  }

  return null;
}

/** Games within this long of each other count as one session. */
const SESSION_GAP = 60 * 60 * 1000;

/**
 * A water break is due before every third game of a session (after games 2, 4, 6…).
 * Returns the id of the game that triggered it, so it's only shown once, or null.
 */
export function waterBreakDue(history: GameRecord[], now: number): string | null {
  const games = [...history].sort((a, b) => b.date - a.date);
  let count = 0;
  let last = now;
  for (const g of games) {
    if (last - g.date > SESSION_GAP) break;
    count++;
    last = g.date;
  }
  return count > 0 && count % 2 === 0 ? games[0].id : null;
}

export const WATER_BREAK: PartyPrompt = {
  emoji: '💧',
  title: 'Hydration Break',
  body: 'Two games down. Everybody drinks a full glass of water before the first serve.',
  sound: 'whoosh',
};

// --- Loser's Wheel ------------------------------------------------------------
// Spun from the game-over screen. {loser} / {winner} are team names.

export const LOSERS_WHEEL = [
  '{loser}, {sips:2}.',
  '{winner} pick the house rule for the next game.',
  "{loser} carry the winners' paddles to the next game.",
  '{loser} serve the first point of the next game with their off hand.',
  '{loser} perform a victory dance in honor of {winner}.',
  '{loser} call the score for the whole next game in a sports-announcer voice.',
  "{loser}: compliment each winner's best shot. Out loud. With feeling.",
  'Lucky spin! {loser} get off free this time.',
  '{loser} owe {winner} a cold drink after the session.',
  'Rematch! If {loser} lose again, they {finish}.',
];

/** Spin the wheel: every outcome, rendered for the current spice, and which one it landed on. */
export function spinLosersWheel(
  loser: string,
  winner: string,
  spice: Spice,
  rng: () => number = Math.random,
): { options: string[]; landed: number } {
  const options = LOSERS_WHEEL.map((t) => fill(t, { loser, winner }, spice, rng));
  return { options, landed: Math.floor(rng() * options.length) };
}

// --- Chaos Rules ----------------------------------------------------------------
// A Court Rule changes how play works for everyone. With Chaos Rules on, a new one
// is drawn every few points; whoever breaks it loses the rally.

export const CHAOS_EVERY = 3;

const pointsPlayed = (s: MatchState) => s.scores[0] + s.scores[1];

/** True when the rally just scored should bring in a new Court Rule. */
export function courtRuleDue(before: MatchState, after: MatchState): boolean {
  const points = pointsPlayed(after);
  return after.winner === null && points > pointsPlayed(before) && points % CHAOS_EVERY === 0;
}

/** Points left before the next Court Rule. */
export const pointsUntilNextRule = (s: MatchState) => CHAOS_EVERY - (pointsPlayed(s) % CHAOS_EVERY);

export function courtRulePrompt(text: string, spice: Spice, opts: { tab?: boolean } = {}): PartyPrompt {
  return { emoji: '🌀', title: 'New Court Rule', body: renderPenalty(text, spice, Math.random, opts), sound: 'whoosh' };
}

export function ruleBrokenPrompt(who: string, them: string): PartyPrompt {
  return { emoji: '🚫', title: 'Rule Broken', body: `${who} broke the Court Rule. ${them} win the rally.`, sound: 'honk' };
}

// --- Party Rules: the Bar Tab ---------------------------------------------------
// Nobody drinks mid-game in Party Rules (the drinks are on the bench): penalties go on
// each team's tab, paid when the teams switch ends and when the game ends.

/** The tab after a charge (both teams, for a 'both' charge). */
export function addToTab(tab: [number, number], charge?: TabCharge): [number, number] {
  if (!charge || charge.sips <= 0) return tab;
  const next = [...tab] as [number, number];
  for (const t of [0, 1] as Team[]) if (charge.team === 'both' || charge.team === t) next[t] += charge.sips;
  return next;
}

const sipsText = (n: number) => `${n} sip${n === 1 ? '' : 's'}`;

/** "Lob Squad: 3 sips. Dink Floyd: 1 sip." (only teams that owe something). */
export function tabLine(tab: [number, number], names: [string, string]): string {
  return ([0, 1] as Team[])
    .filter((t) => tab[t] > 0)
    .map((t) => `${names[t]}: ${sipsText(tab[t])}.`)
    .join(' ');
}

/** Halfway: change ends, and pay the tab on the way past the bench. */
export function switchPrompt(tab: [number, number], names: [string, string], useTab: boolean): PartyPrompt {
  const owed = tabLine(tab, names);
  return {
    emoji: '🔄',
    title: useTab ? 'Switch & Sip' : 'Switch Ends',
    body: !useTab
      ? 'Halfway! Change ends, and grab some water on the way past the bench.'
      : owed
        ? `Halfway! Change ends and pay your tab on the way past the bench. ${owed}`
        : 'Halfway! Change ends. Clean tabs: nobody owes a thing.',
    sound: 'whoosh',
  };
}

/** The end of a Party Rules game: everyone settles up, the losers rotate off, the winners stay on. */
export function lastCallPrompt(
  tab: [number, number],
  winner: Team,
  names: [string, string],
  pickled: boolean,
): PartyPrompt {
  const loser = other(winner);
  const winnerOwes = tab[winner] > 0 ? ` ${names[winner]}: ${sipsText(tab[winner])}.` : '';
  return {
    emoji: pickled ? '🥒' : '🍻',
    title: pickled ? 'PICKLED!' : winsTitle(names[winner]),
    body:
      `Last call! ${names[loser]} pay the tab on the way off: ${sipsText(tab[loser])}.${winnerOwes} ` +
      `${names[winner]} stay on. Next team up!`,
    big: true,
    sound: pickled ? 'airhorn' : 'kazoo',
  };
}
